import sys; sys.path.insert(0, ".")
import limits, csv, collections
print("plan," + ",".join(limits.FACTORS))
for p in limits.PLANS:
    print(p + "," + ",".join(str(limits.limit_for(p, r)) for r in limits.FACTORS))
for p in limits.PLANS:
    for r,f in limits.FACTORS.items():
        x = limits.PLANS[p]*f
        if x != round(x): print("float drift", p, r, repr(x))
rows = list(csv.DictReader(open("accounts.csv")))
c = collections.Counter((a["plan"], a["region"]) for a in rows)
print(len(rows), "accounts;", len(c), "plan/region combos used")
print("unknown:", [k for k in c if k[0] not in limits.PLANS or k[1] not in limits.FACTORS])
print("capped accounts:", sum(v for (p,r),v in c.items() if p=="free" and r in limits.CAPPED_REGIONS))
'

